/** A seat's 9-max seat order: the big blind 8, the small blind 7, else 8 minus the players left to act behind it. */
int StyleOrder9(const PlayerView& V, int Idx)
{
	if (Idx == V.BbIdx)
	{
		return 8;
	}
	if (Idx == V.SbIdx)
	{
		return 7;
	}
	const int N = static_cast<int>(V.Seats.size());
	int Behind = 0;
	for (int K = 1; K < N; ++K)
	{
		const int I = (Idx + K) % N;
		++Behind;
		if (I == V.BbIdx)
		{
			break;
		}
	}
	const int Order = 8 - Behind;
	return Order < 0 ? 0 : Order;
}

/** Acting order after the flop: the small blind first, then the big blind, then UTG to the button. */
int StylePostflopOrder(int Order9)
{
	return Order9 == 7 ? 0 : Order9 == 8 ? 1 : Order9 + 2;
}

PreflopNode StylePreflopNode(const PlayerView& V, size_t Prefix)
{
	PreflopNode N;
	const double Bb = bot_detail::BbOf(V);
	const int Count = static_cast<int>(V.Seats.size());
	std::vector<bool> Folded(static_cast<size_t>(Count), false);
	int FirstRaiser = -1;
	int LastRaiser = -1;
	bool LastAllIn = false;
	double LastTo = 0;
	const int MySeat = V.Seats[static_cast<size_t>(V.Me)].Seat;
	const size_t End = std::min(Prefix, V.History.size());
	for (size_t I = 0; I < End; ++I)
	{
		const ActionRecord& A = V.History[I];
		if (A.OnStreet != Street::Preflop)
		{
			break;
		}
		const int Idx = SeatIndex(V, A.Seat);
		if (Idx < 0)
		{
			continue;
		}
		if (A.Type == ActionType::Fold)
		{
			Folded[static_cast<size_t>(Idx)] = true;
		}
		else if (A.Type == ActionType::Raise || A.Type == ActionType::Bet)
		{
			++N.Raises;
			FirstRaiser = FirstRaiser < 0 ? Idx : FirstRaiser;
			LastRaiser = Idx;
			LastAllIn = A.AllIn;
			LastTo = static_cast<double>(A.To);
			N.Callers = 0;
		}
		else if (A.Type == ActionType::Call)
		{
			if (N.Raises == 0)
			{
				++N.Limpers;
			}
			else if (A.Seat != MySeat)
			{
				++N.Callers;
			}
		}
	}
	auto StartOf = [&](int Idx) {
		const PublicSeat& S = V.Seats[static_cast<size_t>(Idx)];
		return static_cast<double>(S.Stack + S.Committed);
	};
	const double Mine = StartOf(V.Me);
	double Deepest = 0;
	for (int I = 0; I < Count; ++I)
	{
		if (I != V.Me && !Folded[static_cast<size_t>(I)])
		{
			Deepest = Max(Deepest, StartOf(I));
		}
	}
	N.Me = StyleOrder9(V, V.Me);
	N.E = Min(Mine, Deepest > 0 ? Deepest : Mine) / Bb;
	N.Ante = static_cast<double>(V.Ante) / Bb;
	N.LastRaiseBb = LastTo / Bb;
	if (N.Raises == 0)
	{
		N.K = PreflopNode::Kind::Unopened;
		return N;
	}
	N.Vs = StyleOrder9(V, LastRaiser);
	N.Opener = StyleOrder9(V, FirstRaiser);
	N.IOpened = FirstRaiser == V.Me;
	N.Ip = StylePostflopOrder(N.Me) > StylePostflopOrder(N.Vs);
	N.JamBb = StartOf(LastRaiser) / Bb;
	// A raise all in, or one that would take all of the stack it leaves me: a jam.
	if (LastAllIn || LastTo >= 0.8 * Mine)
	{
		N.K = PreflopNode::Kind::VsJam;
	}
	else
	{
		N.K = N.Raises == 1 ? PreflopNode::Kind::VsOpen : N.Raises == 2 ? PreflopNode::Kind::Vs3Bet : PreflopNode::Kind::Vs4Bet;
	}
	return N;
}

/**
 * A calibration knob (§2.5's knob 2), off as the spec has it: the charts are chip EV. Turned on, near the money a class
 * plays only inside the chart's share shrunk by the pressure the style feels (its IcmAware x the bots' PressureFor, as
 * the engine's own push rule shrinks its chart: Bot.cpp), and calls shrink by the call squeeze.
 */
constexpr double PushFoldJamSqueeze = 0.0;  // 0.35 tried in round 1: no measurable change in hypers (49.1% -> 49.2%)
constexpr double PushFoldCallSqueeze = 0.0; // 0.5 tried with it

/** The share of combos a chart lookup takes (Lookup(class) for each class). */
template <typename Fn>
double PushFoldShareOf(Fn&& Lookup)
{
	int Combos = 0;
	for (int Cls = 0; Cls < 169; ++Cls)
	{
		Combos += Lookup(Cls) ? HandClassCombos(Cls) : 0;
	}
	return static_cast<double>(Combos) / 1326.0;
}

/** In the set, and inside its share shrunk by the pressure (or simply in the set with no pressure). */
template <typename Fn>
bool PushFoldSqueezed(Fn&& Lookup, int HandClass, double Squeeze)
{
	if (!Lookup(HandClass))
	{
		return false;
	}
	return Squeeze <= 0.0 || charts::charts_detail::ClassMid(HandClass) <= PushFoldShareOf(Lookup) * (1.0 - Squeeze);
}

PreflopPlan StylePushFoldPlan(const PreflopNode& N, int HandClass, double Wide)
{
	using namespace charts;
	PreflopPlan Plan;
	if (N.E > 25.0)
	{
		return Plan;
	}
	const double Ante = N.Ante;
	const double JamSqueeze = PushFoldJamSqueeze * Max(0.0, Min(1.0, N.Pressure));
	const double CallSqueeze = PushFoldCallSqueeze * Max(0.0, Min(1.0, N.Pressure));
	auto JamFirstIn = [&](int Pos, double E) {
		if (JamSqueeze > 0.0 || Wide > 1.0)
		{
			// The push order's threshold: shrunk by the bubble, widened by tilt (as Tilted() widens an open).
			return charts_detail::JamOrderShare(Pos, Ante, HandClass) <= charts_detail::JamShare(Pos, E, Ante) * (1.0 - JamSqueeze) * Max(1.0, Wide);
		}
		return Jam(Pos, E, Ante, HandClass);
	};
	switch (N.K)
	{
	case PreflopNode::Kind::Unopened:
	{
		Plan.Known = true;
		if (N.E <= 15.0 || N.Limpers > 0)
		{
			// Jam or fold (over limpers too: no limps, no min-raises). The big blind over limpers jams like the small blind.
			const int Pos = N.Me >= 8 ? 7 : N.Me;
			Plan.Jam = true;
			Plan.F.Raise = JamFirstIn(Pos, Min(N.E, 20.0)) ? 1.0 : 0.0;
			return Plan;
		}
		// 15 to 25 big blinds: the 25 BB open chart at 2.0x, as GTO plays it.
		Plan.F = charts_detail::PreflopWide(Spot::Rfi, N.Me, 0, N.E, HandClass, Wide * (1.0 - JamSqueeze));
		Plan.F.Call = 0.0;
		Plan.RaiseToBb = 2.0;
		return Plan;
	}
	case PreflopNode::Kind::VsOpen:
	{
		Plan.Known = true;
		Plan.Jam = true;
		const int Bucket = charts_detail::OpenerBucket(N.Vs);
		const double E = Max(N.E, 15.0);
		const bool Shove = PushFoldSqueezed([&](int Cls) { return Reshove(Bucket, N.Me, E, Ante, Cls); }, HandClass, JamSqueeze) ||
			(Wide > 1.0 && charts_detail::ClassMid(HandClass) <= 0.06 * Wide && N.Callers == 0);
		Plan.F.Raise = Shove ? 1.0 : 0.0;
		// The big blind at 20 BB or more also flats the top 30%.
		if (!Shove && N.Me == 8 && N.E >= 20.0 && N.Callers == 0 && charts_detail::ClassMid(HandClass) <= 0.30 * (1.0 - CallSqueeze))
		{
			Plan.F.Call = 1.0;
		}
		return Plan;
	}
	case PreflopNode::Kind::VsJam:
	{
		const double J = Min(N.JamBb, N.E);
		if (N.IOpened)
		{
			// I opened and was re-jammed: the opener's call of a re-shove.
			Plan.Known = true;
			const int Bucket = charts_detail::OpenerBucket(N.Me);
			const double E = Max(J, 15.0);
			Plan.F.Call = PushFoldSqueezed([&](int Cls) { return CallReshove(Bucket, N.Vs, E, Ante, Cls); }, HandClass, CallSqueeze) ? 1.0 : 0.0;
			return Plan;
		}
		if (J > 20.0 || N.Vs > 7 || N.Me <= N.Vs)
		{
			return Plan;
		}
		Plan.Known = true;
		const bool Multiway = N.Callers > 0;
		Plan.F.Call = PushFoldSqueezed([&](int Cls) { return CallJam(N.Vs, N.Me, J, Ante, Cls, Multiway); }, HandClass, CallSqueeze) ? 1.0 : 0.0;
		return Plan;
	}
	default:
		if (N.IOpened)
		{
			// A 3-bet into my short-stack open: the re-shove's call range jams it.
			Plan.Known = true;
			Plan.Jam = true;
			const int Bucket = charts_detail::OpenerBucket(N.Me);
			const double E = Max(N.E, 15.0);
			Plan.F.Raise = PushFoldSqueezed([&](int Cls) { return CallReshove(Bucket, N.Vs, E, Ante, Cls); }, HandClass, CallSqueeze) ? 1.0 : 0.0;
			return Plan;
		}
		return Plan;
	}
}

PlayerAction StylePlanAction(const PlayerView& V, const PreflopPlan& Plan, double U)
{
	const PublicSeat& Me = V.Seats[static_cast<size_t>(V.Me)];
	const double Bb = bot_detail::BbOf(V);
	if (U < Plan.F.Raise && V.CanRaise)
	{
		const double To = Plan.RaiseToBb * Bb;
		if (Plan.Jam || To >= 0.4 * static_cast<double>(Me.Stack + Me.StreetBet))
		{
			return bot_detail::AllIn(V);
		}
		return PlayerAction::RaiseTo(To);
	}
	if (U < Plan.F.Raise + Plan.F.Call || (U < Plan.F.Raise && !V.CanRaise))
	{
		return V.ToCall > 0 ? PlayerAction::Call() : PlayerAction::Check();
	}
	return V.CanCheck ? PlayerAction::Check() : PlayerAction::Fold();
}

BotDecision StylePushFoldDecide(const HeroContext& C, const HeroBrain& B, const Profile& P, double Tilt, Rng& R)
{
	(void)B;
	const PlayerView& V = C.View;
	if (V.CurrentStreet == Street::Preflop && V.Hole.size() == 2)
	{
		PreflopNode N = StylePreflopNode(V, V.History.size());
		N.Pressure = C.Pressure * P.IcmAware;
		const int Cls = HandClass(V.Hole[0], V.Hole[1]);
		const PreflopPlan Plan = StylePushFoldPlan(N, Cls, StyleTiltWide(Tilt));
		if (Plan.Known)
		{
			const double U = Mix(C.MixSeed, C.Tick, C.HeroIdx, static_cast<int>(V.History.size()), SaltPushFold);
			return StyleChoice(V, StylePlanAction(V, Plan, U), 1.0 - charts::charts_detail::ClassMid(Cls));
		}
	}
	// Deeper, and after the flop: the Push/Fold profile through the engine's decision.
	return StyleDecideProfile(C, P, Tilt, R);
}
